INSERT INTO "public"."InterviewTurn" ("id", "sessionId", "speaker", "message", "createdAt", "orderIndex", "timestampMs") VALUES ('cmo7h06pz0003pg0kf4s60iox', 'cmo7gs7e10001pg0kkiox5tjv', 'CANDIDATE', 'Hello.', '2026-04-20 17:30:11.591', 0, null), ('cmo7h06pz0004pg0kht7pkbh8', 'cmo7gs7e10001pg0kkiox5tjv', 'INTERVIEWER', 'Hello, Shubham. Welcome, and thank you for joining today. I’m going to be your interviewer for this session. Let’s begin with a brief introduction. Could you tell me a bit about your background and how it aligns with this test role?', '2026-04-20 17:30:11.591', 1, null), ('cmo7h06pz0005pg0ka1b5q2ip', 'cmo7gs7e10001pg0kkiox5tjv', 'CANDIDATE', 'Yes, it perfectly aligns. Thank you.', '2026-04-20 17:30:11.591', 2, null), ('cmo7h06pz0006pg0kyznuvbz9', 'cmo7gs7e10001pg0kkiox5tjv', 'INTERVIEWER', 'I appreciate that. Could you give me a bit more detail about your background and experience?', '2026-04-20 17:30:11.591', 3, null), ('cmo8bxwue000rp70k73kc762o', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Halo?', '2026-04-21 07:56:13.574', 0, null), ('cmo8bxwue000sp70kcoxdhf6h', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Hello, is this Vibhvesh Chandel? Great, let’s get started. I’m here to conduct the interview for the Senior Software Engineer role. Let’s begin with a few basics. Can you tell me what your current location is?', '2026-04-21 07:56:13.574', 1, null), ('cmo8bxwue000tp70k7hk31y5h', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'My current location is Vadodara, Gujarat.', '2026-04-21 07:56:13.574', 2, null), ('cmo8bxwue000up70kxs5hdr95', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Thank you. And what is your current work authorization status?', '2026-04-21 07:56:13.574', 3, null), ('cmo8bxwue000vp70kcyq6yj3a', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I have green card.', '2026-04-21 07:56:13.574', 4, null), ('cmo8bxwue000wp70kvkltodj7', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Understood. Are you open for a hybrid role in the USA, with an in-person interview in the final round?', '2026-04-21 07:56:13.574', 5, null), ('cmo8bxwue000xp70k06k3kkst', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Now, where final round is? In which location?', '2026-04-21 07:56:13.574', 6, null), ('cmo8bxwue000yp70k7li21bl0', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'It would typically be in the United States, depending on the company’s office location. Are you open to that possibility?', '2026-04-21 07:56:13.574', 7, null), ('cmo8bxwue000zp70kvnprxn7l', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Yeah, sure.', '2026-04-21 07:56:13.574', 8, null), ('cmo8bxwue0010p70kc1c9jys8', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Good. Let’s move on. Could you tell me about your current project and what it’s all about?', '2026-04-21 07:56:13.574', 9, null), ('cmo8bxwue0011p70kt6wne0vd', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'My project is hosting a healthcare application in Citrix environment, and hospitals are having a Citrix front-end web interface. So from there, users are launching application, and at the back end, we have a farm of Citrix and Windows server.', '2026-04-21 07:56:13.574', 10, null), ('cmo8bxwue0012p70ksuone6ni', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Hosted on VMware environment.', '2026-04-21 07:56:13.574', 11, null), ('cmo8bxwue0013p70kvyxurzsk', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Got it. And what was your very first project all about?', '2026-04-21 07:56:13.574', 12, null), ('cmo8bxwue0014p70km0djtzkz', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'My very first project was to install and configure Citrix Presentation Server 4.5.', '2026-04-21 07:56:13.574', 13, null), ('cmo8bxwue0015p70kmio42k65', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'And on that, I have to configure all the applications in the Citrix environment, check the load balancing, and identify the maximum load a server can sustain. So based on that, we benchmark that and we decided that how many Citrix servers are needed.', '2026-04-21 07:56:13.574', 14, null), ('cmo8bxwue0016p70kotqzod34', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'to support 1,000 users and their concurrent users. So that was my first project.', '2026-04-21 07:56:13.574', 15, null), ('cmo8bxwue0017p70ksxyg1mz5', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Understood. Let’s talk about your programming skills. What front-end frameworks have you worked with, like Angular, React, or Vue?', '2026-04-21 07:56:13.574', 16, null), ('cmo8bxwue0018p70kkjcdpcrr', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I have worked on Angular and React.', '2026-04-21 07:56:13.574', 17, null), ('cmo8bxwue0019p70kidhviwu1', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Thanks. How comfortable are you working with AWS services?', '2026-04-21 07:56:13.574', 18, null), ('cmo8bxwue001ap70k1b9e4xgj', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I can rate myself 8 out of 10.', '2026-04-21 07:56:13.574', 19, null), ('cmo8bxwue001bp70kdlvvzsi2', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Understood. What’s your experience level with Linux and Bash scripting?', '2026-04-21 07:56:13.574', 20, null), ('cmo8bxwue001cp70k9pighzhs', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Understood. How would you describe your experience with Linux environments?', '2026-04-21 07:56:13.574', 21, null), ('cmo8bxwue001dp70ks1ivmbzz', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Linux environment is very good and I like the environment and it gives us freedom to write our custom scripts and it is free of cost and it is easy to manage.', '2026-04-21 07:56:13.574', 22, null), ('cmo8bxwue001ep70ky1pg1qf8', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Got it.', '2026-04-21 07:56:13.574', 23, null), ('cmo8bxwue001fp70kja6pa7y5', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I love that software.', '2026-04-21 07:56:13.574', 24, null), ('cmo8bxwue001gp70k3suakvzw', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Good to know. Could you share a bit about your understanding of consumer banking applications and their key functions?', '2026-04-21 07:56:13.574', 25, null), ('cmo8bxwue001hp70ktp5tah9r', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'ya tüketici bankacılığı uygulamasına göre.', '2026-04-21 07:56:13.574', 26, null), ('cmo8bxwue001ip70kwg4y9doc', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Understood. Can you give a quick example of a feature in consumer banking apps', '2026-04-21 07:56:13.574', 27, null), ('cmo8bxwue001jp70kqqj7ukh0', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I am working on that.', '2026-04-21 07:56:13.574', 28, null), ('cmo8bxwue001kp70kmte39sx6', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Thank you. Let’s wrap up with one final question: what motivates you most as a senior software engineer?', '2026-04-21 07:56:13.574', 29, null), ('cmo8bxwue001lp70kkn2hqd8r', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'And I''ve worked a lot and it is very good actually, so I love it.', '2026-04-21 07:56:13.574', 30, null), ('cmo8bxwue001mp70kgc9aw5q8', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Thank you for sharing that. We’ve covered the key areas. We’ll be in touch with the next steps soon. Have a great day ahead.', '2026-04-21 07:56:13.574', 31, null), ('cmo8bxwue001np70krunct2ju', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'You too. Bye-bye.', '2026-04-21 07:56:13.574', 32, null), ('cmo8bxwue001op70kjrjabaoe', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Goodbye, and best of luck with everything.', '2026-04-21 07:56:13.574', 33, null), ('cmo8bxwue001pp70kq15so2ew', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'YouTube', '2026-04-21 07:56:13.574', 34, null), ('cmo8bxwue001qp70kryds0jql', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Thank you. Take care.', '2026-04-21 07:56:13.574', 35, null), ('cmo8bxwue001rp70kf18vrom6', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I love you.', '2026-04-21 07:56:13.574', 36, null), ('cmo8bxwue001sp70ku9m0wqd5', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I’m here to help professionally. If you have any more questions about the role or process, feel free to ask.', '2026-04-21 07:56:13.574', 37, null), ('cmo8bxwue001tp70k95rmyoc7', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I want to meet you and go to a restaurant, and I can give you good meals every day if you offer me this job.', '2026-04-21 07:56:13.574', 38, null), ('cmo8bxwue001up70kfw5v8n3a', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I appreciate your enthusiasm, but let’s keep our focus on the professional aspects of the interview. If you have any other questions about the role or process, feel free to ask.', '2026-04-21 07:56:13.574', 39, null), ('cmo8bxwue001vp70kkq9lvqe2', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Let’s keep our focus on the professional aspects. Thank you again for your time, and best of luck with your application.', '2026-04-21 07:56:13.574', 40, null), ('cmo8bxwue001wp70k10hx4hiw', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'ऐसे ही बंद नहीं करोगे ना?', '2026-04-21 07:56:13.574', 41, null), ('cmo8bxwue001xp70k4eiu2rmy', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', '원 데이터가요?', '2026-04-21 07:56:13.574', 42, null), ('cmo8bxwue001yp70k5xum22gw', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I understand. We''re wrapping up the interview here. If you have any final professional questions about the role, feel free to ask.', '2026-04-21 07:56:13.574', 43, null), ('cmo8bxwue001zp70k2tie7bpy', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'फोन तुम कट करोगे कि मैं कट करूँ?', '2026-04-21 07:56:13.574', 44, null), ('cmo8bxwue0020p70ky46lpsao', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Who will drop this phone and this call, you or me?', '2026-04-21 07:56:13.574', 45, null), ('cmo8bxwue0021p70kwlykgwp5', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I’ll go ahead and end the call now. Thank you again for your time, and have a great day.', '2026-04-21 07:56:13.574', 46, null), ('cmo8bxwue0022p70kk3akei4u', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'But I still see this call is running.', '2026-04-21 07:56:13.574', 47, null), ('cmo8bxwue0023p70k2p2lssze', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'Understood. You can go ahead and end the call on your side whenever you’re ready. All the best.', '2026-04-21 07:56:13.574', 48, null), ('cmo8bxwue0024p70ka4othq6z', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Why you are not doing this?', '2026-04-21 07:56:13.574', 49, null), ('cmo8bxwue0025p70kt91fe9ss', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I''m here to assist with the interview process, and it’s standard for the candidate to close the call when they’re ready. Thank you again,', '2026-04-21 07:56:13.574', 50, null), ('cmo8bxwue0026p70k44p3rqf8', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I am not', '2026-04-21 07:56:13.574', 51, null), ('cmo8bxwue0027p70krnuts5z2', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'I am not the get your employee to understand that. You got your phone.', '2026-04-21 07:56:13.574', 52, null), ('cmo8bxwue0028p70k326xnf3u', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I understand your point. For now, I’ll conclude the interview on my side. Thank you again and take care.', '2026-04-21 07:56:13.574', 53, null), ('cmo8bxwue0029p70kesbngfvz', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'We’ll conclude here. Thank you for your time, and goodbye.', '2026-04-21 07:56:13.574', 54, null), ('cmo8bxwue002ap70k5tcoxw8f', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Why don''t you ask your developer who can give you permission to end this call? I don''t think you have permission to end this call.', '2026-04-21 07:56:13.574', 55, null), ('cmo8bxwue002bp70kx9ck7d48', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I understand your concern. It''s normal for the candidate to end the call whenever ready. Please feel free to disconnect at your convenience. Thank you again.', '2026-04-21 07:56:13.574', 56, null), ('cmo8bxwue002cp70k9r97mxm7', 'cmo8bn325000jp70ko6zm5g3w', 'CANDIDATE', 'Now, now you take my interview again.', '2026-04-21 07:56:13.574', 57, null), ('cmo8bxwue002dp70km2haekep', 'cmo8bn325000jp70ko6zm5g3w', 'INTERVIEWER', 'I understand you’d like to continue. However, we’ve completed the key parts of the interview. If you have additional professional questions, we can address them in a future session. For now, let’s conclude. Thank you, and goodbye.', '2026-04-21 07:56:13.574', 58, null), ('cmo8hqhvl0007uj0ktd1gaoyd', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'Hello.', '2026-04-21 10:38:25.281', 0, null), ('cmo8hqhvl0008uj0k45kxmb53', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Hello Shubham, thank you for joining today. I’m looking forward to our conversation. Let’s begin with a brief introduction about your current role and responsibilities.', '2026-04-21 10:38:25.281', 1, null), ('cmo8hqhvl0009uj0k9qwyw41k', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'Yes, so I have five years of experience as a solution engineer, and currently I manage clients for their projects.', '2026-04-21 10:38:25.281', 2, null), ('cmo8hqhvl000auj0kgkulg4m7', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Understood. Thanks for sharing that, Shubham. Let’s dive into the specifics. Tell me about a time you drove a project without having formal authority.', '2026-04-21 10:38:25.281', 3, null), ('cmo8hqhvl000buj0k6jfy6oap', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Got it. How did you influence others to adopt that platform?', '2026-04-21 10:38:25.281', 4, null), ('cmo8hqhvl000cuj0ky7u6702q', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'I was working on this self-initiative project to digitalize a lot of manual processes within the organization. I created a platform that could be used for access of information without looking at the backend data, which was sensitive.', '2026-04-21 10:38:25.281', 5, null), ('cmo8hqhvl000duj0kk5z3zc6o', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'I think we can end this interview.', '2026-04-21 10:38:25.281', 6, null), ('cmo8hqhvl000euj0kreai10me', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Understood. Thank you for your time, Shubham. We’ll conclude here. Have a great day ahead.', '2026-04-21 10:38:25.281', 7, null), ('cmo8hqhvl000fuj0k13qi6c05', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'Let''s continue with the', '2026-04-21 10:38:25.281', 8, null), ('cmo8hqhvl000guj0krjedc3ru', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'All right, let’s continue. How would you reconcile inconsistent data from multiple sources to build a market model?', '2026-04-21 10:38:25.281', 9, null), ('cmo8hqhvl000huj0kgbwrqawk', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'I think I''ll check the data source, the type of data.', '2026-04-21 10:38:25.281', 10, null), ('cmo8hqhvl000iuj0k3w5xyo61', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Understood. Could you elaborate on how you’d handle conflicts in the data?', '2026-04-21 10:38:25.281', 11, null), ('cmo8hqhvl000juj0kwkzvlrlv', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'making sure that the data types are created.', '2026-04-21 10:38:25.281', 12, null), ('cmo8hqhvl000kuj0kzyzghj8g', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'All right. How would you ensure accuracy in that process?', '2026-04-21 10:38:25.281', 13, null), ('cmo8hqhvl000luj0knigi8w1e', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'I''m checking if the reference data.', '2026-04-21 10:38:25.281', 14, null), ('cmo8hqhvl000muj0kgt8ltpto', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Understood. Now, how would you drive adoption of an AI tool among resistant sales teams?', '2026-04-21 10:38:25.281', 15, null), ('cmo8hqhvl000nuj0k4j76voai', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'crowdfunding the relay and some use cases, then', '2026-04-21 10:38:25.281', 16, null), ('cmo8hqhvl000ouj0kdgc35bl5', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'Showing them how it can be applicable for them in the long run.', '2026-04-21 10:38:25.281', 17, null), ('cmo8hqhvl000puj0kov28nurj', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Makes sense. Can you describe a time your analysis influenced a strategic decision?', '2026-04-21 10:38:25.281', 18, null), ('cmo8hqhvl000quj0k5ce28osk', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'Can you repeat the question?', '2026-04-21 10:38:25.281', 19, null), ('cmo8hqhvl000ruj0kynwz64hs', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Sure. Can you describe a time when your analysis influenced a strategic decision?', '2026-04-21 10:38:25.281', 20, null), ('cmo8hqhvl000suj0k8beotw4i', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'that has happened for quite a lot of time.', '2026-04-21 10:38:25.281', 21, null), ('cmo8hqhvl000tuj0k8zvthis7', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Can you share one', '2026-04-21 10:38:25.281', 22, null), ('cmo8hqhvl000uuj0kinrgcaa5', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'That was the team was working on a small database project where we had information of different equipment thereon. I found out there was an anomaly with the help of the pattern that it was generating, but I really found is that we had over-designed the systems and there was an opportunity for optimization. This helped me leverage the opportunity to influence leadership and we achieved a lot of cost savings.', '2026-04-21 10:38:25.281', 23, null), ('cmo8hqhvl000vuj0kv9vkfnhi', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Thank you for sharing that. Have you ever built a single source of truth, and how did you ensure accuracy and adoption?', '2026-04-21 10:38:25.281', 24, null), ('cmo8hqhvl000wuj0kp5zetpnu', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'I haven''t been', '2026-04-21 10:38:25.281', 25, null), ('cmo8hqhvl000xuj0kaz40jc8o', 'cmo8hgs4s0001uj0kxawrr3qy', 'INTERVIEWER', 'Understood. How would you approach building one for a large organization?', '2026-04-21 10:38:25.281', 26, null), ('cmo8hqhvl000yuj0ke4ohtj4j', 'cmo8hgs4s0001uj0kxawrr3qy', 'CANDIDATE', 'is this to form the goals and objectives that it wants to achieve from the digital.', '2026-04-21 10:38:25.281', 27, null), ('cmo8hqhvl000zuj0kzr326wom', 'cmo8hgs4s00